APP_JS = r"""'use strict';
const STATES=['Burgenland','Kärnten','Niederösterreich','Oberösterreich','Salzburg','Steiermark','Tirol','Vorarlberg','Wien','Unbekannt'];
const byId=id=>document.getElementById(id);const list=byId('results'),count=byId('count'),search=byId('search'),past=byId('past'),cancelled=byId('cancelled'),changes=byId('changes'),sort=byId('sort'),month=byId('month'),days=byId('days');let events=[];
function node(tag,className,text){const item=document.createElement(tag);if(className)item.className=className;if(text!==undefined)item.textContent=text;return item}
function safeLink(url){try{const parsed=new URL(url,location.href);return ['http:','https:'].includes(parsed.protocol)?parsed.href:null}catch{return null}}
function checkbox(container,value,checked){const label=node('label');const input=node('input');input.type='checkbox';input.value=value;input.checked=checked;label.append(input,document.createTextNode(` ${value}`));container.append(label)}
function selected(selector){return new Set([...document.querySelectorAll(selector)].filter(item=>item.checked).map(item=>item.value))}
function slug(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('de').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function updateFeeds(states){const target=byId('selected-feeds');target.replaceChildren(document.createTextNode('Ausgewählte Feeds: '));[...states].filter(value=>value!=='Unbekannt').forEach((value,index)=>{if(index)target.append(document.createTextNode(' · '));const link=node('a','',value);link.href=`feeds/neu-${slug(value)}.xml`;target.append(link)})}
function updateHeaderFeeds(states){const target=byId('header-feeds');target.replaceChildren();[...states].filter(value=>value!=='Unbekannt').forEach(value=>{const link=node('a','',`RSS ${value}`);link.href=`feeds/neu-${slug(value)}.xml`;target.append(link)})}
function isChanged(event){return Boolean(event.changed_at)&&!event.baseline}
function save(){const state={q:search.value,states:[...selected('#states input')],genres:[...selected('#genres input')],month:month.value,days:days.value,past:past.checked,cancelled:cancelled.checked,changes:changes.checked,sort:sort.value};localStorage.setItem('capeet-filters',JSON.stringify(state));const params=new URLSearchParams();if(state.q)params.set('q',state.q);if(state.states.length!==1||state.states[0]!=='Wien')params.set('states',state.states.join(','));if(state.genres.length)params.set('genres',state.genres.join(','));if(state.month)params.set('month',state.month);if(state.days)params.set('days',state.days);if(!state.past)params.set('past','0');if(state.cancelled)params.set('cancelled','1');if(state.changes)params.set('changed','1');if(state.sort!=='discovered-desc')params.set('sort',state.sort);history.replaceState(null,'',`${location.pathname}${params.size?'?'+params:''}`)}
function card(event){const article=node('article',`card ${event.status==='cancelled'?'cancelled':''}`);article.append(node('p','date',new Intl.DateTimeFormat('de-AT',{weekday:'short',day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(`${event.event_date}T12:00:00`))));const heading=node('h2');event.artists.forEach((artist,index)=>{if(index)heading.append(document.createTextNode(' · '));const href=safeLink(artist.link);if(href){const link=node('a','',artist.name);link.href=href;link.rel='noopener noreferrer';heading.append(link)}else heading.append(document.createTextNode(artist.name));if(artist.country)heading.append(document.createTextNode(` (${artist.country})`))});article.append(heading);if(event.title)article.append(node('p','title',event.title));article.append(node('p','place',`${event.venue} · ${event.postal_code?event.postal_code+' ':''}${event.city}`));const badges=node('p','badges');badges.append(node('span','badge',event.state),node('span','badge',event.genre.family));event.genre.subgenres.forEach(value=>badges.append(node('span','badge',value)));if(event.status==='cancelled')badges.append(node('span','badge alert','Abgesagt'));if(event.status==='postponed')badges.append(node('span','badge alert','Verschoben'));if(!event.active)badges.append(node('span','badge alert','Nicht mehr gelistet'));if(isChanged(event))badges.append(node('span','badge change',event.revision===1?'Neu':'Geändert'));article.append(badges);article.append(node('p','source',`Entdeckt am: ${event.first_seen_at?new Intl.DateTimeFormat('de-AT',{dateStyle:'medium'}).format(new Date(event.first_seen_at)):'–'} · Geändert am: ${event.changed_at?new Intl.DateTimeFormat('de-AT',{dateStyle:'medium'}).format(new Date(event.changed_at)):'–'}`));const links=node('p','links');event.links.forEach(item=>{const href=safeLink(item.url);if(!href)return;const link=node('a','',item.label);link.href=href;link.rel='noopener noreferrer';links.append(link)});const source=node('a','','Capeet-Quellseite');source.href='https://www.capeet.com/gigs_list.html';source.rel='noopener noreferrer';links.append(source);article.append(links);return article}
function render(){const stateSet=selected('#states input'),genreSet=selected('#genres input'),query=search.value.trim().toLocaleLowerCase('de'),today=new Date(),start=new Date(today.getFullYear(),today.getMonth(),today.getDate()),limit=days.value?new Date(today.getFullYear(),today.getMonth(),today.getDate()+Number(days.value)):null;let visible=events.filter(event=>{const words=[event.title,event.venue,event.city,event.source_text,...event.artists.map(item=>item.name)].join(' ').toLocaleLowerCase('de'),date=new Date(`${event.event_date}T12:00:00`),monthMatch=!month.value||event.event_date.slice(0,7)===month.value,daysMatch=!limit||(date>=start&&date<=limit),pastMatch=!past.checked||date>=start;return stateSet.has(event.state)&&(!genreSet.size||genreSet.has(event.genre.family))&&monthMatch&&daysMatch&&pastMatch&&(!query||words.includes(query))&&(cancelled.checked||event.status!=='cancelled')&&(!changes.checked||isChanged(event))});const compare={'discovered-desc':(a,b)=>(b.first_seen_at||'').localeCompare(a.first_seen_at||''),'changed-desc':(a,b)=>(b.changed_at||'').localeCompare(a.changed_at||''),'date-asc':(a,b)=>a.event_date.localeCompare(b.event_date),'date-desc':(a,b)=>b.event_date.localeCompare(a.event_date)}[sort.value];visible.sort(compare);list.replaceChildren(...visible.map(card));count.textContent=`${visible.length} ${visible.length===1?'Termin':'Termine'} angezeigt`;updateFeeds(stateSet);updateHeaderFeeds(stateSet);save()}
function restore(){let saved={};try{saved=JSON.parse(localStorage.getItem('capeet-filters')||'{}')}catch{}const params=new URLSearchParams(location.search);search.value=params.get('q')??saved.q??'';month.value=params.get('month')??saved.month??'';days.value=params.get('days')??saved.days??'';past.checked=params.has('past')?params.get('past')!=='0':saved.past??true;cancelled.checked=params.has('cancelled')||Boolean(saved.cancelled);changes.checked=params.has('changed')||Boolean(saved.changes);sort.value=params.get('sort')||saved.sort||'discovered-desc';const requested=params.has('states')?(params.get('states')||'').split(','):(saved.states||['Wien']);document.querySelectorAll('#states input').forEach(item=>item.checked=requested.includes(item.value));const genres=params.has('genres')?(params.get('genres')||'').split(','):(saved.genres||[]);document.querySelectorAll('#genres input').forEach(item=>item.checked=genres.includes(item.value))}
async function start(){try{const response=await fetch('data/gigs.json');if(!response.ok)throw new Error('HTTP');const payload=await response.json();events=payload.events;STATES.forEach(value=>checkbox(byId('states'),value,value==='Wien'));[...new Set(events.map(item=>item.genre.family))].sort((a,b)=>a.localeCompare(b,'de')).forEach(value=>checkbox(byId('genres'),value,false));[...new Set(events.map(item=>item.event_date.slice(0,7)))].sort().forEach(value=>{const option=node('option','',new Intl.DateTimeFormat('de-AT',{month:'long',year:'numeric'}).format(new Date(`${value}-01T12:00:00`)));option.value=value;month.append(option)});restore();const stamp=`Aktualisiert ${new Intl.DateTimeFormat('de-AT',{dateStyle:'medium',timeStyle:'short'}).format(new Date(payload.generated_at))} · ${events.length} Gigs`;byId('header-metadata').textContent=stamp;byId('metadata').textContent=`${stamp} · Quelle zuletzt geprüft: ${new Intl.DateTimeFormat('de-AT',{dateStyle:'medium',timeStyle:'short'}).format(new Date(payload.source_checked_at))}`;render()}catch{count.textContent='Die Konzertdaten konnten nicht geladen werden.'}}
document.addEventListener('input',event=>{if(event.target.closest('.controls'))render()});document.querySelectorAll('[data-states]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('#states input').forEach(item=>item.checked=button.dataset.states==='all');render()}));byId('reset').addEventListener('click',()=>{search.value='';month.value='';days.value='';past.checked=true;cancelled.checked=false;changes.checked=false;sort.value='discovered-desc';document.querySelectorAll('#states input').forEach(item=>item.checked=item.value==='Wien');document.querySelectorAll('#genres input').forEach(item=>item.checked=false);render()});start();
"""


def generate_site(events: list[Event], revisions: list[dict], output_dir: Path, site_url: str, generated_at: datetime, *, feed_limit: int = 100, feed_days: int = 90) -> None:
    output_dir.parent.mkdir(parents=True, exist_ok=True)
    staging = Path(tempfile.mkdtemp(prefix=f".{output_dir.name}.", dir=output_dir.parent))
    backup = output_dir.with_name(f".{output_dir.name}.previous")
    try:
        atomic_write_text(staging / "index.html", INDEX_HTML)
        atomic_write_text(staging / "assets/styles.css", STYLES_CSS)
        atomic_write_text(staging / "assets/app.js", APP_JS)
        atomic_write_json(staging / "data/gigs.json", {"generated_at": generated_at.isoformat(), "source_checked_at": generated_at.isoformat(), "source_url": "https://www.capeet.com/gigs_list.html", "events": [event.to_dict() for event in events]})
        atomic_write_text(staging / ".nojekyll", "")
        generate_feeds(revisions, staging, site_url, generated_at, limit=feed_limit, days=feed_days)
        if backup.exists():
            shutil.rmtree(backup)
        if output_dir.exists():
            os.replace(output_dir, backup)
        os.replace(staging, output_dir)
        if backup.exists():
            shutil.rmtree(backup)
    except BaseException:
        if not output_dir.exists() and backup.exists():
            os.replace(backup, output_dir)
        shutil.rmtree(staging, ignore_errors=True)
        raise
